def nlp_vocabulary_building(corpus: list, max_vocab_size: int = 5, unk_token: str = '<UNK>') -> dict:
    wc = {}
    for t in corpus:
        for w in t.lower().split(): wc[w] = wc.get(w, 0) + 1
    vocab = [unk_token] + sorted(wc.keys(), key=lambda w: (-wc[w], w))[:int(max_vocab_size) - 1]
    w2i = {w: i for i, w in enumerate(vocab)}
    return {'vocabulary': vocab, 'encoded_corpus': [[w2i.get(w, w2i[unk_token]) for w in t.lower().split()] for t in corpus]}
```

