import numpy as np

def numpy_row_scaling(A: list, norm_type: str = 'l2', eps: float = 1e-12) -> list:
    arr = np.array(A, dtype=float)
    if norm_type == 'l1': norms = np.sum(np.abs(arr), axis=1, keepdims=True)
    elif norm_type == 'max': norms = np.max(np.abs(arr), axis=1, keepdims=True)
    else: norms = np.linalg.norm(arr, ord=2, axis=1, keepdims=True)
    return np.round(arr / np.where(norms > eps, norms, 1.0), 4).tolist()
```

